ALTER TABLE public.transfers ADD COLUMN IF NOT EXISTS delivery_method text NOT NULL DEFAULT 'Bank transfer';
CREATE OR REPLACE FUNCTION public.generate_mtcn() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.mtcn IS NULL OR NEW.mtcn = '' THEN NEW.mtcn := lpad(((('x' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 15))::bit(60)::bigint % 10000000000))::text, 10, '0'); END IF; NEW.updated_at := now(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.create_admin_transfer(p_sender_first_name text, p_sender_last_name text, p_sender_phone text, p_receiver_first_name text, p_receiver_last_name text, p_receiver_country text, p_send_amount numeric, p_send_currency text, p_receive_amount numeric, p_receive_currency text, p_status text, p_status_detail text, p_delivery_method text) RETURNS public.transfers LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE created public.transfers; attempt integer; BEGIN IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN RAISE EXCEPTION 'Not authorized'; END IF; IF trim(coalesce(p_sender_first_name,'')) = '' OR p_send_amount IS NULL OR p_send_amount < 0 THEN RAISE EXCEPTION 'Invalid transfer details'; END IF; FOR attempt IN 1..10 LOOP BEGIN INSERT INTO public.transfers (mtcn, sender_first_name, sender_last_name, sender_phone, receiver_first_name, receiver_last_name, receiver_country, send_amount, send_currency, receive_amount, receive_currency, status, status_detail, delivery_method) VALUES ('', p_sender_first_name, p_sender_last_name, p_sender_phone, p_receiver_first_name, p_receiver_last_name, p_receiver_country, p_send_amount, p_send_currency, p_receive_amount, p_receive_currency, p_status, p_status_detail, p_delivery_method) RETURNING * INTO created; RETURN created; EXCEPTION WHEN unique_violation THEN IF EXISTS (SELECT 1 FROM public.transfers WHERE mtcn = created.mtcn) THEN NULL; END IF; END; END LOOP; RAISE EXCEPTION 'Unable to generate a transfer number'; END $$;
REVOKE ALL ON FUNCTION public.create_admin_transfer(text,text,text,text,text,text,numeric,text,numeric,text,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_admin_transfer(text,text,text,text,text,text,numeric,text,numeric,text,text,text,text) TO authenticated;